using System.Text.RegularExpressions;
using Microsoft.Extensions.Options;
using MyMind.Application.Common;

namespace MyMind.Infrastructure.Storage;

public sealed class StorageOptions
{
    public const string Section = "Storage";

    /// <summary>Directory for uploads; in Docker the <c>uploads</c> volume, which Caddy serves at /uploads.</summary>
    public string Root { get; set; } = "uploads";

    public string PublicBasePath { get; set; } = "/uploads";
}

/// <summary>Files on a local disk or volume. Keys are generated by the app and checked again here.</summary>
public sealed partial class LocalFileStorage(IOptions<StorageOptions> options) : IFileStorage
{
    private readonly string _root = Path.GetFullPath(options.Value.Root);
    private readonly string _publicBase = options.Value.PublicBasePath.TrimEnd('/') + "/";

    public async Task SaveAsync(string key, byte[] content, string contentType, CancellationToken cancellationToken)
    {
        var path = PathFor(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        // Write to a temporary file first so readers never see a half-written image.
        var temporary = path + ".tmp";
        await File.WriteAllBytesAsync(temporary, content, cancellationToken);
        File.Move(temporary, path, overwrite: true);
    }

    public Task DeleteAsync(string key, CancellationToken cancellationToken)
    {
        File.Delete(PathFor(key));
        return Task.CompletedTask;
    }

    public string PublicUrl(string key) => _publicBase + key;

    public string? KeyFromPublicUrl(string url) =>
        url.StartsWith(_publicBase, StringComparison.Ordinal) && SafeKey().IsMatch(url[_publicBase.Length..])
            ? url[_publicBase.Length..]
            : null;

    private string PathFor(string key)
    {
        if (!SafeKey().IsMatch(key))
        {
            throw new ArgumentException($"Unsafe storage key: {key}", nameof(key));
        }

        var path = Path.GetFullPath(Path.Combine(_root, key));
        return path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal)
            ? path
            : throw new ArgumentException($"Storage key escapes the root: {key}", nameof(key));
    }

    [GeneratedRegex("^[a-z0-9]+(?:/[a-z0-9]+)*/[a-z0-9-]+\\.webp$")]
    private static partial Regex SafeKey();
}
